Triage parse(String ticket) {
    Triage t = chat.prompt().user(ticket).call().entity(Triage.class);
    List<String> errors = validate(t);
    if (errors.isEmpty()) {
        return t;
    }
    return chat.prompt()
        .user(ticket + "\n\nYour previous answer was invalid: " + errors + ". Answer again.")
        .call()
        .entity(Triage.class);
}

